Lemma store_ok_sub : forall M (a : word) n (b : word) m,
  bv_unsigned a + Z.of_nat n <= 2 ^ 64 ->
  store_ok SEGS M a n = true ->
  bv_unsigned a <= bv_unsigned b -> bv_unsigned b + Z.of_nat m <= bv_unsigned a + Z.of_nat n ->
  store_ok SEGS M b m = true.
Proof.
